    // because pathname always begins with '/', so the match can only start
    // at a segment boundary.
    const names = bare === pathname ||
      bare + '/' === pathname ||
      bare === pathname + '/' ||
      (bare.length > pathname.length && bare.lastIndexOf(pathname) === bare.length - pathname.length);
